  const [submitStatus, setSubmitStatus] = useState({ type: '', message: '' });
  const [blogs, setBlogs] = useState([]);
  const [loadingBlogs, setLoadingBlogs] = useState(true);

  useEffect(() => {
    const fetchBlogs = async () => {
      try {
        const data = await getLandingPageBlogs();
        setBlogs(data);
      } catch (error) {
